var number Amount = Round([Avg $/Invoice Line]);
var number MyNumber = $Amount; 

var text Final = If(IsNull($MyNumber),"","$" &
Part(ToFormattedText(Abs($MyNumber),"comma_dot",3),1,"."));
//& "." & PadRight(Part(ToText(Abs($MyNumber)),2,"."),2,"0"));

var text A = "<div style=\"background-color:#CCFFCC;\">" & $Final & "</div>";        //pale green
var text B = "<div style=\"background-color:#FFFFFF;\">" & $Final & "</div>";        //white
var text C = "<div style=\"background-color:#FFFFCC;\">" & $Final & "</div>";        //pale yellow
var text D = "<div style=\"background-color:#FFCCCC;\">" & $Final & "</div>";        //pale red

If([Avg $/Invoice Line]>2000,$A,
   [Avg $/Invoice Line]>500,$B,
   [Avg $/Invoice Line]>200,$C,$D
   )

var bool NilA = If([# of Line Items L90d]=0,true);
var bool NilB = If([# of Line Items 90-180d]=0,true);
//var bool NilC = If([# of Line Items LY90d]=0,true);

