//var number GrowthYear = ([# of Line Items L90d]-[# of Line Items LY90d])/[# of Line Items LY90d];

var text Word = If($NilA = true, "Stale",
                     $NilB = true, "Fresh"
                      );
                      
var text Percent = If($NilA = true, "",
                      $NilB = true, "",
                      ToText(Round($GrowthNow,0.01) * 100) & "%"
                      );
                     

var number PercentNumber = If($NilA = true, -1,
                            $NilB = true, +1,
                            $GrowthNow
